import React, { useEffect, useMemo, useState } from 'react';
import { motion } from 'framer-motion';

/* IMPORT STAFF NAVBAR */
import StaffNavbar from '../components/StaffNavbar';

/* =========================
   BANNER
========================= */
function Banner() {
  return (
    <div className="relative w-full h-[500px] bg-[#1a1a1a] flex items-center justify-center overflow-hidden font-['DM_Sans']">

      <div
        className="absolute inset-0 opacity-40 bg-cover bg-center"
        style={{
          backgroundImage:
            "url('https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?q=80&w=2000')",
        }}
      />

      <div className="relative z-10 text-center px-6 max-w-4xl">

        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="text-[#d4af37] text-[10px] font-black tracking-[0.4em] uppercase mb-4"
        >
          Pastry Project Staff Panel
        </motion.p>

        <motion.h1
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="text-white text-6xl md:text-7xl font-serif mb-8 leading-tight font-bold"
        >
          Staff <br />
          <span className="italic text-[#d4af37]">Dashboard</span>
        </motion.h1>

        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5 }}
          className="text-gray-300 text-sm md:text-base max-w-2xl mx-auto leading-relaxed"
        >
          Manage orders, monitor products, and assist customer transactions in real-time.
        </motion.p>

      </div>

    </div>
  );
}

/* =========================
   STATS CARD
========================= */
function StatsCard({ title, value }) {
  return (
    <motion.div
      whileHover={{ y: -5 }}
      className="bg-white rounded-[30px] shadow-xl p-8 border border-gray-100"
    >
      <p className="text-gray-400 text-[11px] uppercase tracking-[0.3em] font-black mb-3">
        {title}
      </p>

      <h2 className="text-5xl font-bold font-serif text-black">
        {value}
      </h2>
    </motion.div>
  );
}

/* =========================
   PRODUCT ROW
========================= */
function ProductRow({ product }) {
  return (
    <div className="flex items-center justify-between border-b border-gray-100 py-5">

      <div className="flex items-center gap-4">

        <img
          src={`http://localhost/GitHub/Capstone--Development/uploads/${product.image}`}
          alt={product.name}
          className="w-16 h-16 rounded-2xl object-cover"
        />

        <div>
          <h3 className="font-bold text-lg">{product.name}</h3>
          <p className="text-sm text-gray-500">{product.category}</p>
        </div>

      </div>

      <div className="text-right">
        <p className="font-bold text-lg">₱{product.price}</p>
        <p className="text-xs uppercase tracking-widest text-green-600 font-bold">
          Available
        </p>
      </div>

    </div>
  );
}

/* =========================
   MAIN DASHBOARD
========================= */
export default function DashboardStaff() {

  const [products, setProducts] = useState([]);
  const [orders, setOrders] = useState([]);
  const [productsLoading, setProductsLoading] = useState(true);
  const [ordersLoading, setOrdersLoading] = useState(true);
  const loading = productsLoading || ordersLoading;

  const STAFF_BASE = "http://localhost/GitHub/Capstone--Development/staff";

  const isToday = dateString => {
    if (!dateString) return false;
    const date = new Date(dateString);
    const today = new Date();
    return date.toDateString() === today.toDateString();
  };

  const isThisWeek = dateString => {
    if (!dateString) return false;
    const date = new Date(dateString);
    const today = new Date();
    const diffDays = Math.floor((today.setHours(0,0,0,0) - date.setHours(0,0,0,0)) / 86400000);
    return diffDays >= 0 && diffDays < 7;
  };

  const fetchProducts = () => {
    fetch('http://localhost/GitHub/Capstone--Development/customer/api_products.php?action=list')
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) {
          setProducts(data);
        } else {
          setProducts([]);
        }
      })
      .catch(err => {
        console.error("Fetch error:", err);
        setProducts([]);
      })
      .finally(() => setProductsLoading(false));
  };

  const fetchOrders = () => {
    fetch(`${STAFF_BASE}/api_orders.php`)
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) {
          setOrders(data);
        } else {
          setOrders([]);
        }
      })
      .catch(err => {
        console.error("Fetch orders error:", err);
        setOrders([]);
      })
      .finally(() => setOrdersLoading(false));
  };

  useEffect(() => {
    fetchProducts();
    fetchOrders();
  }, []);

  const todayOrders = useMemo(
    () => orders.filter(order => isToday(order.created_at)),
    [orders]
  );

  const pendingOrders = useMemo(
    () => orders.filter(order => order.status === 'Pending'),
    [orders]
  );

  const preparingOrders = useMemo(
    () => orders.filter(order => order.status === 'Preparing'),
    [orders]
  );

  const completedOrders = useMemo(
    () => orders.filter(order => order.status === 'Completed'),
    [orders]
  );

  const totalSalesToday = useMemo(
    () => todayOrders.reduce((sum, order) => sum + Number(order.total || 0), 0),
    [todayOrders]
  );

  const weeklySales = useMemo(
    () => orders
      .filter(order => isThisWeek(order.created_at))
      .reduce((sum, order) => sum + Number(order.total || 0), 0),
    [orders]
  );

  const priorityOrders = useMemo(
    () => orders
      .filter(order => order.status === 'Pending' || order.status === 'Preparing')
      .sort((a, b) => new Date(a.created_at) - new Date(b.created_at)),
    [orders]
  );

  const lowStockProducts = useMemo(
    () => products.filter(product => Number(product.stock) > 0 && Number(product.stock) <= 5),
    [products]
  );

  const outOfStockProducts = useMemo(
    () => products.filter(product => Number(product.stock) === 0),
    [products]
  );

  const mostSoldItems = useMemo(() => {
    const tally = {};

    orders.forEach(order => {
      Array.isArray(order.items) && order.items.forEach(item => {
        const name = item.name || item.product_name || 'Unknown';
        const qty = Number(item.qty) || 0;
        if (!name || qty <= 0) return;
        tally[name] = (tally[name] || 0) + qty;
      });
    });

    return Object.entries(tally)
      .map(([name, qty]) => ({ name, qty }))
      .sort((a, b) => b.qty - a.qty)
      .slice(0, 5);
  }, [orders]);

  /* =========================
     FILTERS
  ========================= */
  const cakes = useMemo(
    () => products.filter(p => p.category?.toLowerCase() === 'cakes'),
    [products]
  );

  const pastries = useMemo(
    () => products.filter(p => p.category?.toLowerCase() !== 'cakes'),
    [products]
  );

  return (

    <div className="bg-[#fafafa] min-h-screen font-['DM_Sans']">

      {/* NAVBAR (FIXED POSITION GUARANTEED VISIBILITY) */}
      <StaffNavbar />

      {/* HERO */}
      <Banner />

      <div className="max-w-7xl mx-auto px-10 py-14">

        {/* STATS */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-8 mb-20">

          <StatsCard title="Total Products" value={products.length} />
          <StatsCard title="Cake Products" value={cakes.length} />
          <StatsCard title="Pastries" value={pastries.length} />
          <StatsCard title="Orders Today" value="24" />

        </div>

        {/* PRODUCT LIST */}
        <section>

          <div className="flex items-center justify-between mb-10">
            <div>
              <p className="text-[#d4af37] text-[10px] font-black tracking-[0.4em] uppercase mb-3">
                Product Monitoring
              </p>

              <h2 className="text-4xl font-serif font-bold tracking-tight">
                Available Products
              </h2>
            </div>
          </div>

          <div className="bg-white rounded-[40px] shadow-2xl p-10">

            {/* LOADING STATE */}
            {loading ? (
              <p className="text-center text-gray-400 py-10">
                Loading products...
              </p>
            ) : products.length === 0 ? (
              <p className="text-center text-gray-400 py-10">
                No products found
              </p>
            ) : (
              products.slice(0, 10).map(product => (
                <ProductRow key={product.id} product={product} />
              ))
            )}

          </div>

        </section>

      </div>

    </div>

  );
}
